     1→import { Screen } from "@prototyp/skeletor";
     2→import { useIsFocused } from "@react-navigation/native";
     3→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     4→import { Membership, type RoomInfo } from "@unomed/react-native-matrix-sdk";
     5→import { MatrixService } from "modules/matrix-client/services";
     6→import { useRoomInitialization } from "modules/timeline/hooks";
     7→import { useEffect, useMemo, useState } from "react";
     8→import { useSafeAreaInsets } from "react-native-safe-area-context";
     9→import { Loading } from "shared/components";
    10→import { RoomHeader, RoomInvite, RoomTimeline } from "./fragments";
    11→
    12→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    13→  route,
    14→  navigation,
    15→}) => {
    16→  const { roomId } = route.params;
    17→  const client = MatrixService.instance;
    18→  const isFocused = useIsFocused();
    19→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
    20→  const insets = useSafeAreaInsets();
    21→  const hasActiveCall = useMemo(
    22→    () => room?.hasActiveRoomCall(),
    23→    [room, isFocused],
    24→  );
    25→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    26→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
    27→  const isRoomInvite = useMemo(() => {
    28→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
    29→  }, [roomInfo, isInviteAccepted]);
    30→
    31→  const { isMembersLoading, roomMembers, hasNoCallOption } =
    32→    useRoomInitialization({ room });
    33→
    34→  useEffect(() => {
    35→    room?.roomInfo().then(setRoomInfo).catch(console.error);
    36→  }, [room]);
    37→
    38→  const handleStartCall = () => {
    39→    if (!client || !room) {
    40→      console.error("Client or room not available");
    41→      return;
    42→    }
    43→
    44→    navigation.navigate("elementCall", {
    45→      roomId,
    46→      roomName: room.displayName(),
    47→    });
    48→  };
    49→
    50→  const handleInviteAccepted = () => {
    51→    setIsInviteAccepted(true);
    52→  };
    53→
    54→  const handleInviteDeclined = () => {
    55→    navigation.goBack();
    56→  };
    57→
    58→  const handleRoomDetails = () => {
    59→    if (isRoomInvite || !room) return;
    60→    navigation.navigate("roomDetails", { room });
    61→  };
    62→
    63→  if (!room) return null;
    64→
    65→  if (!roomInfo) {
    66→    return (
    67→      <Screen hideTopSafeArea scrollable={false}>
    68→        <RoomHeader
    69→          room={room}
    70→          isMembersLoading={isMembersLoading}
    71→          roomMembers={roomMembers}
    72→          hasActiveCall={false}
    73→          hasNoCallOption
    74→          topInset={insets.top}
    75→          onBack={() => navigation.goBack()}
    76→        />
    77→        <Loading isFullScreen={false} />
    78→      </Screen>
    79→    );
    80→  }
    81→
    82→  return (
    83→    <Screen hideTopSafeArea>
    84→      <RoomHeader
    85→        room={room}
    86→        isMembersLoading={isMembersLoading}
    87→        roomMembers={roomMembers}
    88→        hasActiveCall={hasActiveCall ?? false}
    89→        hasNoCallOption={isRoomInvite || hasNoCallOption}
    90→        topInset={insets.top}
    91→        onBack={() => navigation.goBack()}
    92→        onRoomDetails={handleRoomDetails}
    93→        onStartCall={handleStartCall}
    94→      />
    95→
    96→      {isRoomInvite ? (
    97→        <RoomInvite
    98→          roomId={roomId}
    99→          roomInfo={roomInfo}
   100→          onAccepted={handleInviteAccepted}
   101→          onDeclined={handleInviteDeclined}
   102→        />
   103→      ) : (
   104→        <RoomTimeline room={room} roomId={roomId} />
   105→      )}
   106→    </Screen>
   107→  );
   108→};
