    17→export const Encryption: React.FC<
    18→  NativeStackScreenProps<Routes, "encryption">
    19→> = ({ navigation }) => {
    20→  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
    21→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    22→    RecoveryState.Unknown,
    23→  );
    24→  const [isLoading, setIsLoading] = useState<boolean>(true);
    25→  const [isDisableKeyStorageModalVisible, setIsDisableKeyStorageModalVisible] =
    26→    useState<boolean>(false);
    27→  const isBackupEnabled = backupState === "enabled";
    28→  const isTransitioning =
    29→    backupState === "enabling" || backupState === "disabling";
    30→
    31→  const recoveryText = () => {
    32→    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
    33→    if (recoveryState === RecoveryState.Disabled) {
    34→      return "Set up a recovery key";
    35→    }
    36→    if (recoveryState === RecoveryState.Incomplete) {
    37→      return "Enter existing recovery key and validate your device.";
    38→    }
    39→    return "Set up a recovery key";
    40→  };
    41→
    42→  useEffect(() => {
    43→    const listener = MatrixService.subscribeToBackupState((state) => {
    44→      setBackupState(state);
    45→      setIsLoading(false);
    46→    });
    47→
    48→    return () => {
    49→      listener.cancel();
    50→    };
    51→  }, []);
    52→
    53→  useEffect(() => {
    54→    const listener = MatrixService.subscribeToRecoveryState((state) => {
    55→      setRecoveryState(state);
    56→      setIsLoading(false);
    57→    });
    58→
    59→    return () => {
    60→      listener.cancel();
    61→    };
    62→  }, []);
    63→
    64→  const handleToggleKeyStorage = async () => {
    65→    try {
    66→      if (isBackupEnabled) {
    67→        setIsDisableKeyStorageModalVisible(true);
    68→        return;
    69→      }
    70→
    71→      // Enable backups when state is unknown (backup not enabled)
    72→      setIsLoading(true);
    73→      await MatrixService.enableBackups();
    74→      setIsLoading(false);
    75→    } catch (error) {
    76→      console.error("Failed to toggle key storage:", error);
    77→      Toast.show({
    78→        text1: "Failed to toggle key storage",
    79→        text2: error instanceof Error ? error.message : "Unknown error",
    80→        type: "error",
    81→      });
    82→    }
    83→  };
    84→
    85→  return (
    86→    <ScreenLayout>
    87→      <Block flex={1} align="center" gap={40}>
    88→        <GoBackHeader title="Encryption" margins={0} />
    89→        {recoveryState !== RecoveryState.Incomplete && (
    90→          <Block gap={8} width="100%">
    91→            <Text
    92→              size={TextSize.tiny}
    93→              color={Colors.white50}
    94→              paddings={[0, 12]}
    95→            >
    96→              Key storage
    97→            </Text>
    98→            {isLoading ? (
    99→              <Block paddings={[20, 12]} align="center">
   100→                <ActivityIndicator size="small" color={Colors.primary} />
   101→              </Block>
   102→            ) : (
   103→              <RadioButton
   104→                disabled={isTransitioning}
   105→                checked={isBackupEnabled}
   106→                onToggle={handleToggleKeyStorage}
   107→                label="Allow key storage"
   108→              />
   109→            )}
   110→            <Block flexDirection="row" gap={12}>
   111→              <Image source={require("assets/icons/info.png")} />
   112→              <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
   113→                Store your cryptographic identity and message keys securely on
   114→                the server. This will allow you to view your message history on
   115→                any new devices.
   116→              </Text>
   117→            </Block>
   118→          </Block>
   119→        )}
   120→        {isBackupEnabled && (
   121→          <Block width="100%" gap={8}>
   122→            <Button.Wrapper
   123→              style={styles.button}
   124→              onPress={() => navigation.navigate("setUpRecoveryKey")}
   125→            >
   126→              <Block
   127→                paddings={[20, 12]}
   128→                flexDirection="row"
   129→                align="center"
   130→                justify="space-between"
   131→                border={{
   132→                  borderRadius: 16,
   133→                }}
   134→                background={Colors.white5}
   135→              >
   136→                <Text flex={1} size={TextSize.base}>
   137→                  {recoveryText()}
   138→                </Text>
   139→                <Image
   140→                  source={require("assets/icons/caret-left.png")}
   141→                  style={styles.caret}
   142→                />
   143→              </Block>
   144→            </Button.Wrapper>
   145→            <Block flexDirection="row" gap={12}>
   146→              <Image source={require("assets/icons/info.png")} />
   147→              <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
   148→                Get access to your encrypted messages if you lose all your
   149→                devices or are signed out of Cloak everywhere.
   150→              </Text>
   151→            </Block>
   152→          </Block>
   153→        )}
   154→        <DisableKeyStorageModal
   155→          visible={isDisableKeyStorageModalVisible}
   156→          onClose={() => setIsDisableKeyStorageModalVisible(false)}
   157→        />
   158→      </Block>
   159→    </ScreenLayout>
   160→  );
   161→};
   162→
   163→const styles = StyleSheet.create({
   164→  button: {
   165→    width: "100%",
   166→  },
   167→  caret: {
   168→    transform: [{ rotate: "180deg" }],
   169→    width: 24,
   170→    height: 24,
   171→    marginLeft: "auto",
   172→  },
   173→});
