     3→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     4→import { RecoveryState } from "@unomed/react-native-matrix-sdk";
     5→import { SecureStoreKeys } from "modules/matrix-client/models";
     6→import { MatrixService } from "modules/matrix-client/services/matrix-service";
     7→import { useEffect, useState } from "react";
     8→import { Alert, Image, StyleSheet } from "react-native";
     9→import { useMMKVBoolean } from "react-native-mmkv";
    10→import Toast from "react-native-toast-message";
    11→import { Button, Loading, ScreenLayout } from "shared/components";
    12→import { Colors, TextSize } from "shared/styles";
    13→
    14→export const SetUpRecoveryKey: React.FC<
    15→  NativeStackScreenProps<Routes, "setUpRecoveryKey">
    16→> = ({ navigation, route }) => {
    17→  const [recoveryKey, setRecoveryKey] = useState<string | null>(
    18→    route.params?.initialKey ?? null,
    19→  );
    20→  const [isGeneratingRecoveryKey, setIsGeneratingRecoveryKey] = useState(false);
    21→  const [isLoading, setIsLoading] = useState(true);
    22→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    23→    RecoveryState.Unknown,
    24→  );
    25→  const [hasSeenProtectAccountMessage, setHasSeenProtectAccountMessage] =
    26→    useMMKVBoolean(SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE);
    27→
    28→  const recoveryKeyExists = recoveryState === RecoveryState.Enabled;
    29→
    30→  const title = () => {
    31→    if (recoveryKey) return "Recovery key";
    32→    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
    33→    if (recoveryState === RecoveryState.Disabled) {
    34→      return "Set up a recovery key";
    35→    }
    36→    if (recoveryState === RecoveryState.Incomplete) {
    37→      return "Enter existing recovery key and validate your device.";
    38→    }
    39→    return "Set up a recovery key";
    40→  };
    41→
    42→  const buttonText = () => {
    43→    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
    44→    if (recoveryState === RecoveryState.Incomplete) return "Enter existing key";
    45→    if (recoveryState === RecoveryState.Disabled) {
    46→      return "Set up a recovery key";
    47→    }
    48→
    49→    return "Set up a recovery key";
    50→  };
    51→
    52→  const handleGenerateRecoveryKey = async () => {
    53→    try {
    54→      setIsGeneratingRecoveryKey(true);
    55→
    56→      let key: string;
    57→
    58→      // Backup exists (whether Enabled or Incomplete)
    59→      if (recoveryState === RecoveryState.Incomplete) {
    60→        navigation.navigate("enterRecoveryKey");
    61→        return;
    62→      }
    63→
    64→      if (recoveryKeyExists) key = await MatrixService.resetRecoveryKey();
    65→      else key = await MatrixService.enableRecovery();
    66→
    67→      setRecoveryKey(key);
    68→      if (hasSeenProtectAccountMessage) return;
    69→      setHasSeenProtectAccountMessage(true);
    70→    } catch (error) {
    71→      console.error(error);
    72→      Toast.show({
    73→        text1: "Failed to generate recovery key",
    74→        type: "error",
    75→      });
    76→    } finally {
    77→      setIsGeneratingRecoveryKey(false);
    78→    }
    79→  };
    80→
    81→  const handleCopyRecoveryKey = () => {
    82→    if (!recoveryKey) return;
    83→    Clipboard.setString(recoveryKey);
    84→    Toast.show({
    85→      text1: "Recovery key copied to clipboard",
    86→      type: "success",
    87→    });
    88→  };
    89→
    90→  const handleGoBack = () => {
    91→    if (!recoveryKey) {
    92→      navigation.goBack();
    93→      return;
    94→    }
    95→
    96→    Alert.alert(
    97→      "Have you saved the recovery key?",
    98→      "You will not be able to access your new recovery key after this step.",
    99→      [
   100→        { text: "Cancel", style: "cancel" },
   101→        { text: "Continue", onPress: () => navigation.goBack() },
   102→      ],
   103→    );
   104→  };
   105→
   106→  useEffect(() => {
   107→    const taskHandle = MatrixService.subscribeToRecoveryState((state) => {
   108→      setRecoveryState(state);
   109→      setIsLoading(false);
   110→    });
   111→
   112→    return () => {
   113→      taskHandle.cancel();
   114→    };
   115→  }, []);
   116→
   117→  return (
   118→    <ScreenLayout type="modal">
   119→      {isLoading && <Loading />}
   120→      <Block flex={1} align="center">
   121→        <Image style={styles.image} source={require("assets/images/key.png")} />
   122→        <Text
   123→          textAlign="center"
   124→          size={TextSize.large}
   125→          margins={{ marginBottom: 8 }}
   126→        >
   127→          {title()}
   128→        </Text>
   129→        <Text
   130→          textAlign="center"
   131→          size={TextSize.small}
   132→          color={Colors.white50}
   133→          margins={{ marginBottom: 32 }}
   134→        >
   135→          Set up a recovery key so you can restore your encrypted messages if
   136→          you lose access to this and other devices.
   137→        </Text>
   138→        {recoveryKey ? (
   139→          <Block gap={20} width="100%">
   140→            <Block flexDirection="row" align="center" justify="space-between">
   141→              <Text flex={1} textAlign="left" size={TextSize.medium}>
   142→                {recoveryKey}
   143→              </Text>
   144→              <Button.Wrapper onPress={handleCopyRecoveryKey}>
   145→                <Image source={require("assets/icons/copy.png")} />
   146→              </Button.Wrapper>
   147→            </Block>
   148→            <Text size={TextSize.tiny} color={Colors.white50}>
   149→              Tap to copy recovery key
   150→            </Text>
   151→          </Block>
   152→        ) : (
   153→          <Block>
   154→            {isGeneratingRecoveryKey ? (
   155→              <Block>
   156→                <Loading
   157→                  text="Generating recovery key..."
   158→                  isFullScreen={false}
   159→                />
   160→              </Block>
   161→            ) : (
   162→              <Button.Outline onPress={handleGenerateRecoveryKey}>
   163→                {buttonText()}
   164→              </Button.Outline>
   165→            )}
   166→          </Block>
   167→        )}
   168→        <Block
   169→          margins={{ marginTop: "auto" }}
   170→          width="100%"
   171→          paddings={[0, 52]}
   172→          gap={12}
   173→        >
   174→          {recoveryKey && (
   175→            <Button.Outline
   176→              size="medium"
   177→              width="100%"
   178→              onPress={handleCopyRecoveryKey}
   179→            >
   180→              <Image source={require("assets/icons/download.png")} />
   181→              <Text size={TextSize.small}>Save Recovery Key</Text>
   182→            </Button.Outline>
   183→          )}
   184→          <Button.Primary size="medium" width="100%" onPress={handleGoBack}>
   185→            Done
   186→          </Button.Primary>
   187→        </Block>
   188→      </Block>
   189→    </ScreenLayout>
   190→  );
   191→};
   192→
   193→const styles = StyleSheet.create({
   194→  image: {
   195→    marginBottom: 40,
   196→  },
   197→});
