     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     3→import { useAtom } from "jotai";
     4→import { addDateDividers, getEventId } from "modules/matrix-client/utils";
     5→import { useRoomTimeline } from "modules/timeline/hooks";
     6→import { TimelineAtoms } from "modules/timeline/jotai";
     7→import {
     8→  filterSameStateKey,
     9→  handleIsPreviousSameSender,
    10→} from "modules/timeline/utils";
    11→import {
    12→  type FC,
    13→  useCallback,
    14→  useEffect,
    15→  useMemo,
    16→  useRef,
    17→  useState,
    18→} from "react";
    19→import {
    20→  FlatList,
    21→  Image,
    22→  KeyboardAvoidingView,
    23→  type NativeScrollEvent,
    24→  type NativeSyntheticEvent,
    25→  StyleSheet,
    26→} from "react-native";
    27→import {
    28→  Button,
    29→  ImageViewerModal,
    30→  Loading,
    31→  MemberDetailsBottomSheet,
    32→  VideoViewerModal,
    33→} from "shared/components";
    34→import { useMemberDetails } from "shared/hooks";
    35→import { DateDivider } from "../date-divider";
    36→import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
    37→import { RoomInput } from "../room-input";
    38→import { SingleMessageType } from "../single-message-type";
    39→
    40→interface Props {
    41→  room: RoomInterface;
    42→  roomId: string;
    43→}
    44→
    45→export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
    46→  const flatListRef = useRef<FlatList>(null);
    47→  const isAtBottomRef = useRef(true);
    48→  const [showScrollDown, setShowScrollDown] = useState(false);
    49→  const {
    50→    events,
    51→    loadingMessage,
    52→    refreshing,
    53→    updateTrigger,
    54→    isDirect,
    55→    loadMoreMessages,
    56→    markAsRead,
    57→  } = useRoomTimeline({
    58→    room,
    59→    roomId,
    60→  });
    61→  const [scrollToEventId, setScrollToEventId] = useAtom(
    62→    TimelineAtoms.scrollToEventId,
    63→  );
    64→  const {
    65→    selectedMember,
    66→    isBottomSheetOpen,
    67→    openMemberDetails,
    68→    closeMemberDetails,
    69→  } = useMemberDetails();
    70→
    71→  const sortedEvents = useMemo(() => {
    72→    const sorted = [...events].sort(
    73→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    74→    );
    75→
    76→    return filterSameStateKey(sorted);
    77→  }, [events]);
    78→
    79→  const eventsWithDividers = useMemo(() => {
    80→    return addDateDividers(sortedEvents);
    81→  }, [sortedEvents]);
    82→
    83→  const handleScrollToEvent = useCallback(
    84→    (eventId: string) => {
    85→      const index = eventsWithDividers.findIndex(
    86→        (item) => item.type === "event" && getEventId(item.data) === eventId,
    87→      );
    88→      if (index === -1) return;
    89→
    90→      flatListRef.current?.scrollToIndex({
    91→        index,
    92→        animated: true,
    93→        viewPosition: 0.5,
    94→      });
    95→    },
    96→    [eventsWithDividers],
    97→  );
    98→
    99→  useEffect(() => {
   100→    if (!scrollToEventId) return;
   101→    handleScrollToEvent(scrollToEventId);
   102→    setScrollToEventId(null);
   103→  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
   104→
   105→  const handleLoadMore = async () => {
   106→    setShowScrollDown(false);
   107→    await loadMoreMessages();
   108→  };
   109→
   110→  const handleContentSizeChange = () => {
   111→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   112→    if (!isAtBottomRef.current && !lastEvent?.isOwn) return;
   113→    flatListRef.current?.scrollToEnd({ animated: false });
   114→    setTimeout(() => {
   115→      flatListRef.current?.scrollToEnd({ animated: false });
   116→    }, 100);
   117→  };
   118→
   119→  const handleScrollDown = () => {
   120→    flatListRef.current?.scrollToEnd({ animated: true });
   121→    setShowScrollDown(false);
   122→  };
   123→
   124→  const handleOnScroll = ({
   125→    nativeEvent,
   126→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
   127→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
   128→    const paddingToBottom = 100;
   129→    const atBottom =
   130→      layoutMeasurement.height + contentOffset.y >=
   131→      contentSize.height - paddingToBottom;
   132→    isAtBottomRef.current = atBottom;
   133→    if (!atBottom) return;
   134→    setShowScrollDown(false);
   135→    markAsRead();
   136→  };
   137→
   138→  useEffect(() => {
   139→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   140→    if (isAtBottomRef.current || lastEvent?.isOwn) return;
   141→
   142→    setShowScrollDown(true);
   143→  }, [isAtBottomRef.current, sortedEvents]);
   144→
   145→  if (loadingMessage) {
   146→    return (
   147→      <Block flex={1} align="center" justify="center">
   148→        <Loading isFullScreen={false} />
   149→      </Block>
   150→    );
   151→  }
   152→
   153→  return (
   154→    <>
   155→      <KeyboardAvoidingView style={styles.flex} behavior="padding">
   156→        <FlatList
   157→          ref={flatListRef}
   158→          data={eventsWithDividers}
   159→          keyExtractor={(item) => {
   160→            if (item.type === "divider") return item.id;
   161→
   162→            return getEventId(item.data) ?? "";
   163→          }}
   164→          extraData={updateTrigger}
   165→          contentContainerStyle={styles.listContent}
   166→          refreshing={refreshing}
   167→          onContentSizeChange={handleContentSizeChange}
   168→          onRefresh={handleLoadMore}
   169→          onScroll={handleOnScroll}
   170→          onScrollToIndexFailed={(info) => {
   171→            flatListRef.current?.scrollToOffset({
   172→              offset: info.averageItemLength * info.index,
   173→              animated: true,
   174→            });
   175→          }}
   176→          renderItem={({ item }) => {
   177→            if (item.type === "divider") {
   178→              return <DateDivider date={item.date} />;
   179→            }
   180→
   181→            const eventIndex = sortedEvents.findIndex(
   182→              (e) => getEventId(e) === getEventId(item.data),
   183→            );
   184→
   185→            return (
   186→              <SingleMessageType
   187→                event={item.data}
   188→                isPreviousSameSender={handleIsPreviousSameSender(
   189→                  isDirect,
   190→                  sortedEvents,
   191→                  item.data,
   192→                  eventIndex,
   193→                )}
   194→                onMemberPress={openMemberDetails}
   195→              />
   196→            );
   197→          }}
   198→        />
   199→
   200→        <RoomInput roomId={roomId} />
   201→      </KeyboardAvoidingView>
   202→
   203→      <MessageContentBottomSheet roomId={roomId} />
   204→
   205→      <MemberDetailsBottomSheet
   206→        isBottomSheetOpen={isBottomSheetOpen}
   207→        selectedMember={selectedMember}
   208→        roomId={roomId}
   209→        onClose={closeMemberDetails}
   210→      />
   211→
   212→      {showScrollDown && (
   213→        <Block
   214→          absolute
   215→          offsets={{ right: 0, bottom: 100 }}
   216→          align="center"
   217→          justify="center"
   218→          width="100%"
   219→        >
   220→          <Button.Outline size="medium" onPress={handleScrollDown}>
   221→            <Text>New messages</Text>
   222→            <Image source={require("assets/icons/arrow-down.png")} />
   223→          </Button.Outline>
   224→        </Block>
   225→      )}
   226→
   227→      <ImageViewerModal />
   228→      <VideoViewerModal />
   229→    </>
   230→  );
   231→};
   232→
   233→const styles = StyleSheet.create({
   234→  flex: {
   235→    flex: 1,
   236→  },
   237→  listContent: {
   238→    paddingHorizontal: 20,
   239→    paddingTop: 12,
   240→    paddingBottom: 20,
   241→  },
   242→});
