  1658→    console.log("✅ Recovery enabled! Save your recovery key securely.");
  1659→    return recoveryKey;
  1660→  };
  1661→
  1662→  /** Reset the recovery key and get a new one
  1663→   * Use this if you lost your old recovery key*/
  1664→  public static resetRecoveryKey = async () => {
  1665→    if (!this.instance) throw new Error("Client not initialized");
  1666→
  1667→    const encryption = this.instance.encryption();
  1668→    const newRecoveryKey = await encryption.resetRecoveryKey();
  1669→
  1670→    // Perform a full recover round-trip after resetting to ensure all secrets
  1671→    // are verified under the new key and the state transitions to Enabled.
  1672→    // Without this, the SDK's recoveryStateListener may never emit Enabled,
  1673→    // leaving the state stuck at Incomplete indefinitely.
  1674→    await encryption.recover(newRecoveryKey);
  1675→
  1676→    console.log("✅ Recovery key reset! Save your new recovery key securely.");
  1677→    return newRecoveryKey;
  1678→  };
  1679→
  1680→  /** Recover using a recovery key
  1681→   * Use this to restore access to encrypted message */
  1682→  public static recoverWithKey = async (recoveryKey: string) => {
  1683→    if (!this.instance) throw new Error("Client not initialized");
  1684→
  1685→    const encryption = this.instance.encryption();
  1686→    await encryption.recover(recoveryKey);
  1687→
  1688→    console.log("✅ Successfully recovered using recovery key!");
  1689→  };
  1690→
  1691→  /** Disable recovery (removes backup and recovery key)
  1692→   * Warning: This will prevent you from recovering encrypted messages */
  1693→  public static disableRecovery = async () => {
  1694→    if (!this.instance) throw new Error("Client not initialized");
  1695→
  1696→    const encryption = this.instance.encryption();
  1697→    await encryption.disableRecovery();
  1698→
  1699→    console.log("⚠️ Recovery disabled");
  1700→  };
  1701→
  1702→  public static resetIdentity = async () => {
  1703→    if (!this.instance) throw new Error("Client not initialized");
  1704→    await this.instance.encryption().resetIdentity();
