  1706→  };
  1707→
  1708→  // PUSH NOTIFICATIONS METHODS
  1709→
  1710→  /** Get all pushers registered for this user */
  1711→  public static getPushers = async () => {
  1712→    if (!this.instance) throw new Error("Client not initialized");
  1713→
  1714→    const session = this.instance.session();
  1715→    if (!session) throw new Error("No active session");
  1716→
  1717→    try {
  1718→      const response = await fetch(
  1719→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_GET}`,
  1720→        {
  1721→          method: "GET",
  1722→          headers: {
  1723→            "Content-Type": "application/json",
  1724→            Authorization: `Bearer ${session.accessToken}`,
  1725→          },
  1726→        },
  1727→      );
  1728→
  1729→      if (!response.ok) {
  1730→        const errorText = await response.text();
  1731→        throw new Error(
  1732→          `Failed to get pushers: ${response.status} - ${errorText}`,
  1733→        );
  1734→      }
  1735→
  1736→      const data = await response.json();
  1737→      return data.pushers || [];
  1738→    } catch (error) {
  1739→      console.error("Failed to get pushers:", error);
  1740→      throw error;
  1741→    }
  1742→  };
  1743→
  1744→  /** Check if a pusher is already registered for this device */
  1745→  public static isPusherRegistered = async (pushToken: string) => {
  1746→    try {
  1747→      const pushers = await this.getPushers();
  1748→      if (!this.instance) throw new Error("Client not initialized");
  1749→      const session = this.instance.session();
  1750→      if (!session) throw new Error("No active session");
  1751→
  1752→      return pushers.some(
  1753→        (pusher: {
  1754→          pushkey: string;
  1755→          app_id: string;
  1756→          device_display_name: string;
  1757→        }) =>
  1758→          pusher.pushkey === pushToken &&
  1759→          pusher.app_id === APP_ID &&
  1760→          pusher.device_display_name === session.deviceId,
  1761→      );
  1762→    } catch (error) {
  1763→      console.error("Failed to check pusher registration:", error);
  1764→      return false;
  1765→    }
  1766→  };
  1767→
  1768→  /** Register a pusher with the homeserver for push notifications */
  1769→  public static setPusher = async (pushToken: string) => {
