  1771→
  1772→    const session = this.instance.session();
  1773→    if (!session) throw new Error("No active session");
  1774→
  1775→    const pusherData = {
  1776→      pushkey: pushToken,
  1777→      kind: "http",
  1778→      app_id: APP_ID,
  1779→      app_display_name: "Cloak",
  1780→      device_display_name: session.deviceId || "Mobile Device",
  1781→      profile_tag: "", // Optional: for multiple pushers per device
  1782→      lang: "en",
  1783→      data: {
  1784→        url: `${SygnalURL}/${MATRIX_ENDPOINTS.PUSH_GATEWAY_URL}`,
  1785→      },
  1786→    };
  1787→
  1788→    try {
  1789→      const response = await fetch(
  1790→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
  1791→        {
  1792→          method: "POST",
  1793→          headers: {
  1794→            "Content-Type": "application/json",
  1795→            Authorization: `Bearer ${session.accessToken}`,
  1796→          },
  1797→          body: JSON.stringify(pusherData),
  1798→        },
